impl StringResolver {
    pub fn desktop_telex_guide_tone(&self, tone: &str) -> String {
        self.format(StringKey::DesktopTelexGuideTone, &[&tone])
    }

    pub fn desktop_telex_guide_initial(&self, initial: &str) -> String {
        self.format(StringKey::DesktopTelexGuideInitial, &[&initial])
    }

    pub fn desktop_update_current_version_label(&self, version: &str) -> String {
        self.format(StringKey::DesktopUpdateCurrentVersionLabel, &[&version])
    }

    pub fn desktop_update_available_message(&self, latest: &str) -> String {
        self.format(StringKey::DesktopUpdateAvailableMessage, &[&latest])
    }

    pub fn desktop_update_pending_version_label(&self, version: &str) -> String {
        self.format(StringKey::DesktopUpdatePendingVersionLabel, &[&version])
    }

    pub fn desktop_installer_step_failed(&self, step: &str) -> String {
        self.format(StringKey::DesktopInstallerStepFailed, &[&step])
    }

    pub fn dictionary_import_result(&self, imported: i64, skipped: i64) -> String {
        self.format(StringKey::DictionaryImportResult, &[&imported, &skipped])
    }
}
